import { test, expect } from '@playwright/test';

test.describe('Request Timeout Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should display timeout error when request takes longer than 10 seconds', async ({ page }) => {
    // Set up a mock API response with a timeout
    await page.route('**/api/data', (route) => {
      setTimeout(() => {
        route.abort('Request timed out');
      }, 11000);
    });

    // Intercept the request and wait for the timeout
    const responsePromise = page.waitForResponse('**/api/data');

    // Wait for the timeout error to be displayed
    const errorMessage = page.getByText('Request timed out');
    await expect(errorMessage).toBeVisible();

    // Verify the error message contains the expected text
    await expect(errorMessage).toContainText('Request timed out');

    // Verify the error icon is visible
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify the request status is set to failed
    const requestStatus = page.getByRole('status');
    await expect(requestStatus).toHaveText('Failed');

    // Verify the request URL is visible
    const requestUrl = page.getByRole('heading', { name: /api/ });
    await expect(requestUrl).toBeVisible();

    // Verify the error message is displayed with a timeout duration
    const timeoutDuration = page.getByText('Request timed out after 10 seconds');
    await expect(timeoutDuration).toBeVisible();

    // Verify the retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify the retry button is enabled
    await expect(retryButton).toBeEnabled();
  });

  test('should handle request timeout gracefully and display error message', async ({ page }) => {
    // Set up a mock API response with a timeout
    await page.route('**/api/data', (route) => {
      setTimeout(() => {
        route.abort('Request timed out');
      }, 10000);
    });

    // Intercept the request and wait for the timeout
    const responsePromise = page.waitForResponse('**/api/data');

    // Verify the error message is displayed
    const errorMessage = page.getByText('Request timed out');
    await expect(errorMessage).toBeVisible();

    // Verify the error icon is visible
    const errorIcon = page.getByRole('img', { name: /error/i });
    await expect(errorIcon).toBeVisible();

    // Verify the request status is set to failed
    const requestStatus = page.getByRole('status');
    await expect(requestStatus).toHaveText('Failed');

    // Verify the request URL is visible
    const requestUrl = page.getByRole('heading', { name: /api/ });
    await expect(requestUrl).toBeVisible();

    // Verify the error message is displayed with a timeout duration
    const timeoutDuration = page.getByText('Request timed out after 10 seconds');
    await expect(timeoutDuration).toBeVisible();

    // Verify the retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify the retry button is enabled
    await expect(retryButton).toBeEnabled();

    // Verify the user is notified of the error
    const errorNotification = page.getByText('Failed to load data');
    await expect(errorNotification).toBeVisible();

    // Verify the user can navigate away from the error page
    const navigationButton = page.getByRole('button', { name: /back/i });
    await expect(navigationButton).toBeVisible();

    await expect(navigationButton).toBeEnabled();
  });
});
